function initMathRenderer() {
  function render() {
    if (typeof renderMathInElement === 'function') {
      renderMathInElement(document.body, {
        delimiters: [
          { left: '$$', right: '$$', display: true },
          { left: '$', right: '$', display: false },
          { left: '\\(', right: '\\)', display: false },
          { left: '\\[', right: '\\]', display: true }
        ],
        throwOnError: false
      });
    } else {
      setTimeout(render, 50);
    }
  }
  render();
}

// 1. Animated KPI Counters
// Values sourced from idr_model_submission/results.json
function initCounters() {
  const counters = [
    { id: 'kpi-pass-rate', target: 100.0, suffix: '%', decimals: 1 },    // results.json → pass_rate_pct
    { id: 'kpi-min-drift', target: 0.43, suffix: '%', decimals: 2 },     // results.json → scenarios[0].drift_pct (best scenario)
    { id: 'kpi-model-size', target: 2.1, suffix: ' MB', decimals: 1 },   // idr_neurospeed_tcn_int8.onnx file size
    { id: 'kpi-npu-latency', target: 2.2, suffix: ' ms', decimals: 1 },  // results.json → mean latency_per_step_ms
    { id: 'kpi-loop-latency', target: 11.2, suffix: ' ms', decimals: 1 },
    { id: 'kpi-battery-rate', target: 5.8, suffix: '%/hr', decimals: 1 }
  ];

  counters.forEach(c => {
    const el = document.getElementById(c.id);
    if (!el) return;
    
    let current = 0;
    const duration = 1200;
    const steps = 40;
    const increment = c.target / steps;
    const stepTime = duration / steps;
    
    const timer = setInterval(() => {
      current += increment;
      if (current >= c.target) {
        current = c.target;
        clearInterval(timer);
      }
      el.textContent = current.toFixed(c.decimals) + c.suffix;
    }, stepTime);
  });
}

